import { useEffect, useMemo, useRef, useState } from 'react';
import { Route, RouteComponentProps } from 'react-router';

import { useAppTitle } from '@proton/components';
import { LinkURLType } from '@proton/shared/lib/drive/constants';

import DriveView, { DriveSectionRouteProps } from '../components/sections/Drive/DriveView';
import useActiveShare, { DriveFolder } from '../hooks/drive/useActiveShare';
import { useFolderContainerTitle } from '../hooks/drive/useFolderContainerTitle';
import useNavigate from '../hooks/drive/useNavigate';
import { useDefaultShare, useDriveEventManager } from '../store';
import PreviewContainer from './PreviewContainer';

export default function FolderContainer({ match }: RouteComponentProps<DriveSectionRouteProps>) {
    const { navigateToRoot } = useNavigate();
    const { activeFolder, setFolder } = useActiveShare();
    const lastFolderPromise = useRef<Promise<DriveFolder | undefined>>();
    const [, setError] = useState();
    const { getDefaultShare } = useDefaultShare();
    useFolderContainerTitle({ params: match.params, setAppTitle: useAppTitle });
    const events = useDriveEventManager();

    const hasValidLinkType = (type: string) => {
        return type === LinkURLType.FILE || type === LinkURLType.FOLDER;
    };

    const folderPromise = useMemo(async () => {
        const { shareId, type, linkId } = match.params;

        if (!shareId && !type && !linkId) {
            const defaultShare = await getDefaultShare();
            if (defaultShare) {
                return { shareId: defaultShare.shareId, linkId: defaultShare.rootLinkId };
            }
            setError(() => {
                // Throwing error in async function does not propagate it to
                // the view. Therefore we need to use this setError hack.
                throw new Error('Drive is not initilized, cache has been cleared unexpectedly');
            });
        } else if (!shareId || !hasValidLinkType(type as string) || !linkId) {
            console.warn('Missing parameters, should be none or shareId/type/linkId');
            navigateToRoot();
        } else if (type === LinkURLType.FOLDER) {
            return { shareId, linkId };
        }
        return lastFolderPromise.current;
    }, [match.params.shareId, match.params.type, match.params.linkId]);

    useEffect(() => {
        folderPromise
            .then((folder) => {
                if (folder) {
                    setFolder(folder);
                }
            })
            .catch(console.warn);
    }, [folderPromise]);

    // In case we open preview, folder doesn't need to change.
    lastFolderPromise.current = folderPromise;

    const shouldRenderDriveView = Boolean(activeFolder.shareId && activeFolder.linkId);

    useEffect(() => {
        events.shares.startSubscription(activeFolder.shareId).catch(reportError);

        return () => {
            events.shares.pauseSubscription(activeFolder.shareId);
        };
    }, [activeFolder.shareId]);

    return (
        <>
            {shouldRenderDriveView ? <DriveView /> : null}
            <Route path={`/:shareId?/${LinkURLType.FILE}/:linkId?`} component={PreviewContainer} exact />
        </>
    );
}
export enum ShareType {
    default = 1,
    standart,
    device,
}

export interface Share {
    shareId: string;
    rootLinkId: string;
    volumeId: string;
    creator: string;
    isLocked: boolean;
    isDefault: boolean;
    isVolumeSoftDeleted: boolean;
    possibleKeyPackets: string[];
    type: ShareType;
}

export interface ShareWithKey extends Share {
    key: string;
    passphrase: string;
    passphraseSignature: string;
    addressId: string;
    rootLinkRecoveryPassphrase?: string;
}

export interface LockedVolumeForRestore {
    shareId: string;
    lockedVolumeId: string;
    decryptedPassphrase: string;
}

import { createContext, useCallback, useContext, useState } from 'react';

import { LockedVolumeForRestore, Share, ShareWithKey } from './interface';

type SharesState = {
    [shareId: string]: Share | ShareWithKey;
};

/**
 * useSharesStateProvider provides a storage to cache shares.
 */
function useSharesStateProvider() {
    const [state, setState] = useState<SharesState>({});
    const [lockedVolumesForRestore, setLockedVolumesForRestore] = useState<LockedVolumeForRestore[]>([]);

    const setShares = useCallback((shares: (Share | ShareWithKey)[]) => {
        setState((state) => {
            shares.forEach((share) => {
                state[share.shareId] = share;
            });
            return { ...state };
        });
    }, []);

    const removeShares = useCallback((shareIds: string[]) => {
        setState((state) => {
            return Object.fromEntries(Object.entries(state).filter(([shareId]) => !shareIds.includes(shareId)));
        });
    }, []);

    const getShare = useCallback(
        (shareId: string): Share | ShareWithKey | undefined => {
            return state[shareId];
        },
        [state]
    );

    const getLockedShares = useCallback((): (Share | ShareWithKey)[] => {
        return Object.values(state).filter((share) => share.isLocked && share.isDefault && !share.isVolumeSoftDeleted);
    }, [state]);

    const getDefaultShareId = useCallback((): string | undefined => {
        const share = Object.entries(state)
            .map(([, share]) => share)
            .find((share) => share.isDefault && !share.isLocked && !share.isVolumeSoftDeleted);
        return share ? share.shareId : undefined;
    }, [state]);

    return {
        setShares,
        removeShares,
        getShare,
        getLockedShares,
        getDefaultShareId,
        setLockedVolumesForRestore,
        lockedVolumesForRestore,
    };
}

const SharesStateContext = createContext<ReturnType<typeof useSharesStateProvider> | null>(null);

export function SharesStateProvider({ children }: { children: React.ReactNode }) {
    const value = useSharesStateProvider();
    return <SharesStateContext.Provider value={value}>{children}</SharesStateContext.Provider>;
}

export default function useSharesState() {
    const state = useContext(SharesStateContext);
    if (!state) {
        throw new Error('Trying to use uninitialized SharesStateProvider');
    }
    return state;
}
